package binding

import "fmt"

// NewSprintfBool returns a String binding that formats a Bool using fmt.Sprintf.
// The format string should contain a single %v, %t, or similar verb.
// Changes to the input Bool will automatically update the returned String.
//
// Since: 2.5
func NewSprintfBool(format string, b Bool) String {
	str := NewString()

	// Create a listener that updates the string whenever the bool changes
	listener := NewDataListener(func() {
		val, err := b.Get()
		if err != nil {
			return
		}
		formatted := fmt.Sprintf(format, val)
		str.Set(formatted)
	})

	b.AddListener(listener)

	// Trigger initial update
	listener.DataChanged()

	return str
}

// NewSprintfInt returns a String binding that formats an Int using fmt.Sprintf.
// The format string should contain a single %d, %v, or similar verb.
// Changes to the input Int will automatically update the returned String.
//
// Since: 2.5
func NewSprintfInt(format string, i Int) String {
	str := NewString()

	// Create a listener that updates the string whenever the int changes
	listener := NewDataListener(func() {
		val, err := i.Get()
		if err != nil {
			return
		}
		formatted := fmt.Sprintf(format, val)
		str.Set(formatted)
