package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"

	"fyne.io/fyne/v2"
)

// jsonTheme represents a theme loaded from JSON configuration
type jsonTheme struct {
	colorsGeneric map[fyne.ThemeColorName]color.Color
	colorsDark    map[fyne.ThemeColorName]color.Color
	colorsLight   map[fyne.ThemeColorName]color.Color
	sizes         map[fyne.ThemeSizeName]float32
	fonts         map[string]fyne.Resource
	icons         map[fyne.ThemeIconName]fyne.Resource
}

// jsonThemeData represents the JSON structure for theme configuration
type jsonThemeData struct {
	Colors      map[string]string  `json:"Colors"`
	ColorsDark  map[string]string  `json:"Colors-dark"`
	ColorsLight map[string]string  `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string  `json:"Fonts"`
	Icons       map[string]string  `json:"Icons"`
}

// FromJSON creates a fyne.Theme from a JSON byte array.
// On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSON(data []byte) (fyne.Theme, error) {
	var themeData jsonThemeData
	if err := json.Unmarshal(data, &themeData); err != nil {
		return DefaultTheme(), err
	}

	theme := &jsonTheme{
		colorsGeneric: make(map[fyne.ThemeColorName]color.Color),
		colorsDark:    make(map[fyne.ThemeColorName]color.Color),
		colorsLight:   make(map[fyne.ThemeColorName]color.Color),
		sizes:         make(map[fyne.ThemeSizeName]float32),
		fonts:         make(map[string]fyne.Resource),
		icons:         make(map[fyne.ThemeIconName]fyne.Resource),
	}

	// Parse generic colors
	for name, hexColor := range themeData.Colors {
		if col, err := parseHexColor(hexColor); err == nil {
			theme.colorsGeneric[fyne.ThemeColorName(name)] = col
		}
	}

	// Parse dark variant colors
	for name, hexColor := range themeData.ColorsDark {
		if col, err := parseHexColor(hexColor); err == nil {
			theme.colorsDark[fyne.ThemeColorName(name)] = col
		}
	}

	// Parse light variant colors
	for name, hexColor := range themeData.ColorsLight {
		if col, err := parseHexColor(hexColor); err == nil {
			theme.colorsLight[fyne.ThemeColorName(name)] = col
		}
	}

	// Copy sizes
	for name, size := range themeData.Sizes {
		theme.sizes[fyne.ThemeSizeName(name)] = size
	}

	// Load fonts from URIs
	for style, uri := range themeData.Fonts {
		if res, err := fyne.LoadResourceFromURLString(uri); err == nil {
			theme.fonts[style] = res
		}
	}

	// Load icons from URIs
	for name, uri := range themeData.Icons {
		if res, err := fyne.LoadResourceFromURLString(uri); err == nil {
			theme.icons[fyne.ThemeIconName(name)] = res
		}
	}

	return theme, nil
}

// FromJSONReader creates a fyne.Theme by reading JSON from an io.Reader.
// On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSONReader(reader io.Reader) (fyne.Theme, error) {
	data, err := io.ReadAll(reader)
	if err != nil {
		return DefaultTheme(), err
	}
	return FromJSON(data)
}

// parseHexColor converts a hex color string to color.Color
// Supports formats: #RGB, #RGBA, #RRGGBB, #RRGGBBAA
func parseHexColor(hex string) (color.Color, error) {
	if len(hex) > 0 && hex[0] == '#' {
		hex = hex[1:]
	}

	var r, g, b, a uint8 = 0, 0, 0, 255

	switch len(hex) {
	case 3: // #RGB
		r = parseHexByte(hex[0:1]) * 17
		g = parseHexByte(hex[1:2]) * 17
		b = parseHexByte(hex[2:3]) * 17
	case 4: // #RGBA
		r = parseHexByte(hex[0:1]) * 17
		g = parseHexByte(hex[1:2]) * 17
		b = parseHexByte(hex[2:3]) * 17
		a = parseHexByte(hex[3:4]) * 17
	case 6: // #RRGGBB
		r = parseHexByte(hex[0:2])
		g = parseHexByte(hex[2:4])
		b = parseHexByte(hex[4:6])
	case 8: // #RRGGBBAA
		r = parseHexByte(hex[0:2])
		g = parseHexByte(hex[2:4])
		b = parseHexByte(hex[4:6])
		a = parseHexByte(hex[6:8])
	default:
		return nil, fmt.Errorf("invalid hex color format: %s", hex)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexByte converts a hex string to a byte value
func parseHexByte(hex string) uint8 {
	var val uint8
	for i := 0; i < len(hex); i++ {
		val *= 16
		c := hex[i]
		if c >= '0' && c <= '9' {
			val += c - '0'
		} else if c >= 'a' && c <= 'f' {
			val += c - 'a' + 10
		} else if c >= 'A' && c <= 'F' {
			val += c - 'A' + 10
		}
	}
	return val
}

// Color returns the theme's color for the specified named color
// Resolution order: variant-specific, generic Colors, default theme
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	if variant == fyne.VariantDark {
		if col, ok := t.colorsDark[name]; ok {
			return col
		}
	} else if variant == fyne.VariantLight {
		if col, ok := t.colorsLight[name]; ok {
			return col
		}
	}

	// Check generic colors
	if col, ok := t.colorsGeneric[name]; ok {
		return col
	}

	// Fall back to default theme
	return DefaultTheme().Color(name, variant)
}

// Font returns the theme's font resource for the specified text style
func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	// Map TextStyle to string key
	var key string
	if style.Bold && style.Italic {
		key = "bold-italic"
	} else if style.Bold {
		key = "bold"
	} else if style.Italic {
		key = "italic"
	} else if style.Monospace {
		key = "monospace"
	} else {
		key = "regular"
	}

	if font, ok := t.fonts[key]; ok {
		return font
	}

	// Fall back to default theme
	return DefaultTheme().Font(style)
}

// Icon returns the theme's resource for the specified icon name
func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if icon, ok := t.icons[name]; ok {
		return icon
	}
	// Fall back to default theme
	return DefaultTheme().Icon(name)
}

// Size returns the theme's size for the specified named size
func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[name]; ok {
		return size
	}
	// Fall back to default theme
	return DefaultTheme().Size(name)
}

