package validation

import (
	"fmt"
	"strings"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that requires all provided validators to pass.
// The validator will return nil if all validators pass, otherwise returns an error
// combining all validation failures.
//
// Since: 2.5
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		var errors []string

		for _, validator := range validators {
			if validator == nil {
				continue
			}

			err := validator(text)
			if err != nil {
				errors = append(errors, err.Error())
			}
		}

		if len(errors) == 0 {
			return nil
		}

		if len(errors) == 1 {
			return fmt.Errorf("%s", errors[0])
		}

		return fmt.Errorf("%s", strings.Join(errors, "; "))
	}
}

